INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué requisitos debe cumplir una contraseña segura?', 'Las contraseñas deben tener al menos ocho caracteres (recomendado doce o más) e incluir al menos tres de los siguientes elementos: mayúsculas, minúsculas, números y caracteres especiales.', 'contraseña segura requisitos', TRUE, 'IT y seguridad');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cómo puedo restablecer mi contraseña?', 'Ve a la página de restablecimiento de contraseña y responde a las preguntas de seguridad para crear una nueva. Se pedirá renovarla cada 6 meses.', 'restablecer contraseña olvidé', TRUE, 'IT y seguridad');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('No puedo iniciar sesión, ¿dónde obtengo ayuda?', 'Contacta con el administrador de TI desde tu dispositivo móvil registrado, o responde a las preguntas de seguridad para verificar tu identidad.', 'no puedo iniciar sesion acceso', TRUE, 'IT y seguridad');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('Han accedido a mi cuenta sin mi conocimiento, ¿qué hago?', 'Informa de inmediato registrando un incidente o enviando un correo al servicio de TI.', 'cuenta hackeada acceso no autorizado', TRUE, 'IT y seguridad');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué hacer para no compartir accidentalmente información privada?', 'Guarda los documentos y archivos en la nube, no en tu equipo local, y consulta con el equipo de seguridad y protección de datos ante cualquier duda.', 'informacion privada datos', TRUE, 'IT y seguridad');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Dónde denunciar la pérdida o el robo de un dispositivo?', 'Envía un ticket al equipo de seguridad marcado como ''Dispositivo perdido o robado'' para que se le dé prioridad.', 'dispositivo perdido robado movil portatil', TRUE, 'IT y seguridad');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Dónde informar sobre archivos corruptos o phishing?', 'Contacta de inmediato con el equipo de Cyber si sospechas de archivos corruptos o de un intento de phishing por correo.', 'phishing virus archivo corrupto', TRUE, 'IT y seguridad');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué hago si mi ordenador no se enciende?', 'Comprueba que la fuente de alimentación está enchufada y mantén pulsado el botón de encendido 5 segundos. Si persiste, contacta con IT.', 'ordenador no enciende averia', TRUE, 'IT y seguridad');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cómo garantizo una buena conexión en reuniones virtuales?', 'Reduce el número de dispositivos conectados, mantén el router actualizado y, si es posible, contrata una conexión de 100 Mbps o superior.', 'conexion internet reuniones videollamada', TRUE, 'Red y VPN');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cómo accedo a la VPN?', 'Los equipos vienen con la VPN configurada por defecto. Si no puedes conectarte, envía un ticket al equipo de IT.', 'vpn conectar remoto', TRUE, 'Red y VPN');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cómo configuro mi red doméstica para el trabajo híbrido?', 'Configura una red separada para el trabajo y conecta a ella únicamente tus dispositivos profesionales, para mantener la información segura.', 'red domestica teletrabajo wifi', TRUE, 'Red y VPN');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cuándo puedo reservar mi puesto en la oficina (Place)?', 'Graduates y Specialists pueden reservar los jueves; All Stars, los viernes. Las reservas se abren con hasta 3 semanas de antelación.', 'reservar puesto place oficina mesa', TRUE, 'Reserva de puesto (Place)');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Estoy reservando un puesto de trabajo concreto?', 'No, las reservas son por sala o espacio, no por un sitio específico. Una vez en la oficina, cada equipo se organiza libremente.', 'reservar puesto place asiento', TRUE, 'Reserva de puesto (Place)');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Puedo modificar o cancelar una reserva de Place?', 'Sí, en cualquier momento según disponibilidad. Si al final no vas a ir, cancela con antelación para liberar el espacio a otra persona.', 'cancelar modificar reserva place', TRUE, 'Reserva de puesto (Place)');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿También puedo reservar salas de reuniones en Place?', 'Sí, Place permite reservar salas de reuniones; puedes consultar el plano de la oficina con el nombre de cada sala.', 'reservar sala reunion place', TRUE, 'Reserva de puesto (Place)');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué hago si tengo un problema con una reserva de Place?', 'Escribe a People Team para que puedan revisarlo.', 'problema reserva place error', TRUE, 'Reserva de puesto (Place)');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué incluye el seguro médico Sanitas Inicia?', 'Incluye asistencia sanitaria general y con especialistas, pruebas diagnósticas, psicología (hasta 15 sesiones/año), podología (hasta 12 sesiones/año) y odontología (2 limpiezas/año, extracciones incluidas).', 'seguro medico sanitas salud', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cuánto cuesta el seguro médico Sanitas y cómo se paga?', '32,24€ al mes más impuestos, descontado vía retribución flexible y reflejado en la nómina.', 'precio coste sanitas nomina', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué incluye el seguro médico Alan Health?', 'Incluye asistencia premium con más de 51.000 especialistas, psicología (20 a 40 sesiones sin prescripción), más de 50 tratamientos dentales, programa de dolor de espalda y asistencia en viaje.', 'seguro medico alan health salud', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cuánto cuesta el seguro médico Alan Health y cómo se paga?', '51€ al mes por empleado, descontado vía retribución flexible y reflejado en la nómina.', 'precio coste alan nomina', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cómo desactivo un seguro médico (Sanitas o Alan)?', 'Envía un email a people@stemdo.io con copia a mjlimon@stemdo.io antes del 28 de febrero, plazo que marca la aseguradora para tramitar bajas antes de la renovación automática.', 'desactivar baja seguro medico', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué es la retribución flexible y en qué se diferencia de un beneficio social?', 'Un beneficio social lo paga la empresa por encima del sueldo. La retribución flexible es parte de tu propio salario que destinas voluntariamente a ciertos servicios, reduciendo tu IRPF.', 'retribucion flexible beneficio social', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué cubre Payflow en comida?', 'Restaurantes, bares y delivery (Glovo, JustEat, etc.) pagando con la tarjeta Cobee. Exento de IRPF hasta 220€ al mes.', 'payflow comida restaurante cobee', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué cubre Payflow en transporte?', 'Transporte público recurrente (metro, cercanías, autobús). No incluye taxi, VTC, patinetes ni combustible. Exento de IRPF hasta 136€ al mes.', 'payflow transporte publico', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué cubre Payflow en guardería?', 'Educación y cuidado infantil de 0 a 3 años en escuelas autorizadas por el Estado. Exento de IRPF sin límite, salvo en País Vasco (1.000€).', 'payflow guarderia niños', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cuánto puedo ahorrar con la retribución flexible?', 'Depende de cuánto destines a cada servicio; puede suponer un ahorro de hasta un 30-40% frente a pagarlo con el salario neto. Payflow muestra el ahorro en tiempo real.', 'ahorro retribucion flexible payflow', TRUE, 'Beneficios y retribución flexible');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cuándo es mi primera evaluación de desempeño?', 'En el primer quarter que se activa tras cumplir 6 meses desde tu incorporación a STEMDO.', 'evaluacion desempeño primera quarter', TRUE, 'Mi carrera');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cómo informo de una ausencia?', 'Envía un email con antelación a tu Head, al Coordinador de tu proyecto y a people@stemdo.io, y registra la ausencia en Personio (Perfil > Ausencias > Solicitar ausencia).', 'informar ausencia personio', TRUE, 'Ausencias y vacaciones');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cómo gestiono una baja médica?', 'Si tu ausencia supera 4 horas, pide la baja a tu médico de cabecera. Informa a tu jefe de proyecto cuanto antes y registra la baja en Personio en un máximo de 48 horas.', 'baja medica enfermedad personio', TRUE, 'Ausencias y vacaciones');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Qué ausencias retribuidas existen (matrimonio, fallecimiento, mudanza...)?', 'Existen varios supuestos: 15 días naturales por matrimonio, 2-4 días por fallecimiento de familiares según el grado, 1 día por mudanza, entre otros. Se solicitan en Personio > Ausencias > Solicitar ausencia.', 'ausencia retribuida matrimonio fallecimiento mudanza permiso', TRUE, 'Ausencias y vacaciones');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cómo funcionan las ausencias no retribuidas (permiso parental)?', 'Hasta 8 semanas de suspensión del contrato por permiso parental, no retribuidas, continuas o discontinuas. Hay que avisar con al menos 10 días naturales de antelación.', 'permiso parental no retribuido', TRUE, 'Ausencias y vacaciones');
INSERT INTO faq (pregunta, respuesta, palabras_clave, activa, tema) VALUES ('¿Cómo solicito las vacaciones?', 'Solicítalas con un mínimo de 4 semanas de antelación siguiendo el proceso del cliente si aplica, regístralas en Personio una vez aprobadas, e informa a tu supervisor, a People y a tu equipo.', 'solicitar vacaciones dias libres', TRUE, 'Ausencias y vacaciones');
